'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {FIELDS,coords,normalizeProxyStation,adaptProxyResponse,createLegacyProxyFetch}=require('./proxy-adapter');
const a={id:123,geom:{lat:43.3,lon:5.4},gazole_prix:1.7,e10_prix:1.8,ville:'Marseille'};
test('six carburants',()=>assert.equal(Object.keys(FIELDS).length,6));
test('géométrie objet',()=>assert.deepEqual(coords(a),{lat:43.3,lon:5.4}));
test('géométrie legacy',()=>assert.deepEqual(coords({latitude:4330000,longitude:540000}),{lat:43.3,lon:5.4}));
test('coordonnées impossibles',()=>assert.equal(coords({geom:{lat:100,lon:5}}),null));
test('prix gazole',()=>assert.equal(normalizeProxyStation(a,'Gazole').price,1.7));
test('prix E10',()=>assert.equal(normalizeProxyStation(a,'E10').price,1.8));
test('carburant inconnu',()=>assert.throws(()=>normalizeProxyStation(a,'diesel')));
test('prix absent',()=>assert.equal(normalizeProxyStation(a,'SP95'),null));
test('prix nul',()=>assert.equal(normalizeProxyStation({...a,gazole_prix:0},'Gazole'),null));
test('identifiant manquant',()=>assert.equal(normalizeProxyStation({...a,id:null},'Gazole'),null));
test('conservation métadonnées',()=>assert.equal(normalizeProxyStation(a,'Gazole').city,'Marseille'));
test('réponse invalide',()=>assert.throws(()=>adaptProxyResponse({}, {fuel:'Gazole'})));
test('réponse vide ne prouve pas complétude',()=>assert.equal(adaptProxyResponse({results:[]},{fuel:'Gazole'}).complete,false));
test('réponse inférieure à limite ne prouve pas complétude',()=>assert.equal(adaptProxyResponse({results:[a]},{fuel:'Gazole'}).complete,false));
test('réponse pleine ne prouve pas complétude',()=>assert.equal(adaptProxyResponse({results:[a]},{fuel:'Gazole',limit:1}).complete,false));
test('doublons dédupliqués',()=>assert.equal(adaptProxyResponse({results:[a,a]},{fuel:'Gazole'}).stations.length,1));
test('stations sans prix écartées',()=>assert.equal(adaptProxyResponse({results:[a,{...a,id:124,gazole_prix:null}]},{fuel:'Gazole'}).rejected,1));
test('autres carburants filtrés',()=>assert.equal(adaptProxyResponse({results:[a]},{fuel:'SP95'}).stations.length,0));
test('URL proxy construite',async()=>{let url;const fetchLegacy=createLegacyProxyFetch({fetchFn:async u=>{url=u;return {ok:true,json:async()=>({results:[a]})}}});const r=await fetchLegacy({origin:{lat:43.3,lon:5.4},radiusKm:20,fuel:'Gazole'});assert.equal(new URL(url).searchParams.get('dist'),'20');assert.equal(r.stations.length,1)});
test('erreur HTTP propagée',async()=>{const f=createLegacyProxyFetch({fetchFn:async()=>({ok:false,status:503})});await assert.rejects(()=>f({origin:{lat:43.3,lon:5.4},radiusKm:20,fuel:'Gazole'}),/503/)});
test('rayon invalide',async()=>{const f=createLegacyProxyFetch({fetchFn:async()=>{throw Error('unexpected')}});await assert.rejects(()=>f({origin:{lat:43.3,lon:5.4},radiusKm:-1,fuel:'Gazole'}))});
test('signal transmis',async()=>{const controller=new AbortController();let seen;const f=createLegacyProxyFetch({fetchFn:async(_,{signal})=>{seen=signal;return {ok:true,json:async()=>({results:[]})}}});await f({origin:{lat:43.3,lon:5.4},radiusKm:5,fuel:'Gazole',signal:controller.signal});assert.equal(seen,controller.signal)});
test('limite invalide',()=>assert.throws(()=>adaptProxyResponse({results:[]},{fuel:'Gazole',limit:0})));
test('identifiants numériques convertis en texte',()=>assert.equal(normalizeProxyStation(a,'Gazole').id,'123'));
